VALUES ('han-west', '西汉', ARRAY['汉','前汉'], NULL, 'cn', 'east_asia', -202, 2, NULL, 'month', 9, 1, NULL, 'year', -2411, 108, 'ochre', NULL, NULL, '刘邦在楚汉战争后于前202年称帝，定都长安，建立以郡县为骨干、兼行诸侯王国的统治秩序。文景时期休养生息，武帝时中央集权与疆域扩展并进；宣帝以后外戚势力渐强，王莽于9年代汉，西汉告终。')
