VALUES ('xin', '新', ARRAY['新','新莽'], NULL, 'cn', 'east_asia', 9, 1, NULL, 'month', 23, 10, NULL, 'month', 108, 285, 'ochre', NULL, NULL, '王莽于9年1月10日受孺子婴禅让，改国号为新；地皇四年绿林攻入长安，王莽被杀。')
