VALUES ('han-gengshi', '更始', ARRAY['汉','玄汉'], NULL, 'cn', 'east_asia', 23, 1, NULL, 'year', 25, 10, NULL, 'month', 276, 309, 'ochre', NULL, NULL, '绿林军拥立更始帝刘玄，复汉号；赤眉入长安后刘玄降被杀。')
