VALUES ('han-east', '东汉', ARRAY['汉','后汉'], NULL, 'cn', 'east_asia', 25, 8, NULL, 'month', 220, 11, NULL, 'month', 307, 2650, 'ochre', NULL, NULL, '刘秀于25年重建汉室、定都洛阳，初期整顿吏治并恢复社会生产，明、章时期国势较盛，经营西域亦有进展。和帝以后外戚与宦官交替掌权，黄巾起事及州郡割据削弱朝廷；献帝于220年禅位曹丕，东汉结束。')
