VALUES ('ying-zheng', '嬴政', 'qin', ARRAY['嬴政','赵政','秦始皇'], '嬴', '赵', -259, 1, NULL, 'year', -210, 1, NULL, 'year', ARRAY['皇帝'], '秦始皇帝，灭六国统一天下，建立中国首个大一统中央集权帝国。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦始皇"},{"label":"史記/卷006","url":"https://zh.wikisource.org/wiki/史記/卷006"},{"label":"《史记·秦本纪》","url":"https://zh.wikisource.org/wiki/史記/卷005"},{"label":"秦庄襄王纪日及儒略历换算","url":"https://en.wikipedia.org/wiki/King_Zhuangxiang_of_Qin"}]'::jsonb, NULL, NULL, '始皇帝')
