VALUES ('ying-ziying', '子婴', 'qin', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '秦末秦王，赵高废二世后立之，刘邦入关后投降，秦朝终结。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦王子婴"}]'::jsonb, NULL, NULL, '秦王子婴')
