VALUES ('liu-bang', '刘邦', 'han-west', ARRAY[]::text[], NULL, NULL, -256, 1, NULL, 'year', -195, 1, NULL, 'year', ARRAY['皇帝'], '刘邦出身沛县，秦末起兵反秦，先后与项羽争夺天下；前202年称帝、定都长安，建立汉朝。他平定异姓诸侯王并分封同姓王，确立汉初郡国并行格局。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘邦"},{"label":"漢書/卷001下","url":"https://zh.wikisource.org/wiki/漢書/卷001下"},{"label":"交接日期复核来源","url":"https://en.wikipedia.org/wiki/Liu_Bang"}]'::jsonb, '高皇帝', '太祖', '汉高祖')
