VALUES ('xiao-he', '萧何', 'han-west', ARRAY[]::text[], NULL, NULL, -257, 1, NULL, 'year', -193, 1, NULL, 'year', ARRAY['政治家'], '汉初相国，定都长安、制律令，与韩信、张良并称三杰；刘邦入关后保护秦朝图籍，为汉初掌握户籍、地理和郡县资料提供基础。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/萧何"}]'::jsonb, NULL, NULL, NULL)
