VALUES ('han-xin', '韩信', 'han-west', ARRAY[]::text[], NULL, NULL, -231, 1, NULL, 'year', -196, 1, NULL, 'year', ARRAY['军事家'], '汉初大将，破赵燕齐楚，垓下围项羽，后遭诛；因萧何推荐而受刘邦拜将，统军取关中、破赵齐；前196年被吕后与萧何诱杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩信"}]'::jsonb, NULL, NULL, NULL)
