VALUES ('ruzi-ying', '刘婴', 'han-west', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, 24, 1, NULL, 'year', ARRAY['君主'], '刘婴是平帝死后由王莽立为皇太子的刘氏宗室，年幼时被称作“孺子”，始终未正式即皇帝位。王莽于9年建立新朝后将他废置；更始政权兴起后，刘婴在长安被杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孺子婴"}]'::jsonb, NULL, NULL, '孺子婴')
