VALUES ('zhang-qian', '张骞', 'han-west', ARRAY[]::text[], NULL, NULL, -164, 1, NULL, 'year', -114, 1, NULL, 'year', ARRAY['外交家'], '西汉外交家，汉中成固人。建元年间奉汉武帝命出使大月氏，途中被匈奴拘留十余年后返汉；后再次出使乌孙，推动汉朝与西域诸国往来，被誉为“凿空”。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张骞"}]'::jsonb, NULL, NULL, NULL)
