VALUES ('zhang-han', '章邯', 'qin', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['将领'], '秦末将领，曾任少府。陈胜起义后率骊山刑徒镇压起义军，击败项梁；巨鹿之战中秦军被项羽击溃后投降项羽，后受封雍王，楚汉战争中败于刘邦。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/章邯"}]'::jsonb, NULL, NULL, NULL)
