VALUES ('xiang-liang', '项梁', 'chu-west', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['起义领袖','将领'], '项羽叔父，会稽起兵反秦，立楚怀王，战死于定陶；率项氏部众起兵反秦并拥立楚怀王，前208年在定陶遭秦军夜袭战死。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/项梁"}]'::jsonb, NULL, NULL, NULL)
