VALUES ('wei-bao', '魏豹', 'han-gengshi', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['诸侯'], '魏王豹，秦末复立魏国，楚汉间反复，终为韩信所灭。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/魏王豹"}]'::jsonb, NULL, NULL, NULL)
