VALUES ('wang-mang', '王莽', 'xin', ARRAY[]::text[], NULL, NULL, -45, 1, NULL, 'year', 23, 1, NULL, 'year', ARRAY['皇帝'], '新莽开国皇帝，外戚出身，篡汉自立，改革失败，绿林起义而亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王莽"}]'::jsonb, NULL, NULL, '')
