VALUES ('liu-xuan', '刘玄', 'han-gengshi', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '更始帝，绿林军拥立，新莽亡后短暂称帝，后为赤眉所杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/更始帝"}]'::jsonb, NULL, NULL, '更始帝')
