VALUES ('liu-bao', '刘保', 'han-east', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '刘保是安帝与宫人李氏之子，曾被邓氏外戚废为济阴王；安帝死后，宦官迎立他为帝。他恢复皇位后任用宦官，梁氏外戚随后长期掌权，顺帝末年各地灾荒与民变频仍。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/汉顺帝"}]'::jsonb, '孝顺皇帝', NULL, '汉顺帝')
