VALUES ('si-ma-qian', '司马迁', 'han-west', ARRAY[]::text[], NULL, NULL, -145, 1, NULL, 'year', -86, 1, NULL, 'year', ARRAY['史学家'], '汉武帝时太史令，著史记，中国第一部纪传体通史；《史记》含本纪、表、书、世家、列传五体，司马迁称承继父亲遗志完成此书。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马迁"}]'::jsonb, NULL, NULL, NULL)
