VALUES ('ban-chao', '班超', 'han-east', ARRAY[]::text[], NULL, NULL, 32, 1, NULL, 'year', 102, 1, NULL, 'year', ARRAY['外交家','军事家'], '东汉将领、外交家，字仲升，扶风安陵人，班彪之子、班固之弟。永平年间投笔从戎出使西域，经营西域三十余年，击退匈奴势力并促使诸国归附，晚年返洛阳。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/班超"}]'::jsonb, NULL, NULL, NULL)
